import { test } from 'node:test';
import assert from 'node:assert';
import { createState, frame, WIDTH, HEIGHT, BALL_R } from '../game/neon.js';

const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1: Missing Bounce - Ball should bounce off a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below
  state.ball.vy = -100; // Moving up

  frame(ctx, state);
  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced and now be moving down');
});

test('D2: Sticky - Ball should be repositioned out of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h - 2; // Deeply overlapping from bottom
  state.ball.vy = -100;

  frame(ctx, state);
  // If corrected, ball.y + ball.r should be <= brick.y + brick.h (if bouncing from bottom)
  // Wait, if it bounces from bottom, it should be at y = brick.y + brick.h + ball.r
  assert.ok(state.ball.y + BALL_R >= brick.y + brick.h, 'Ball should be moved outside the brick');
});

test('D3: Face vs Corner - Ball should bounce off the side', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; // Just to the left
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving right

  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced off the side');
});

test('D4: Double Inversion - Ball should not invert twice on a seam', () => {
  const state = createState(1);
  // Two bricks at index 0 and 1 are side-by-side
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];

  // Ball is exactly on the seam
  state.ball.x = b1.x + b1.w; 
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 100;

  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have inverted once, not twice');
});

test('D5: Tunneling - Ball should not jump over a brick at high speed', () => {
  const state = createState(5); // Speed is higher
  const brick = state.bricks[0];

  // Position ball just above the brick, but with a huge vy that would skip it
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1; 
  state.ball.vy = 1000; // Very fast moving down

  // The distance it moves in one frame (dt=0.05) is 50px.
  // Brick height is 20px.
  // In current logic, it just checks `collides` at the current position.
  // We need to simulate a step then a frame.

  // Since we are testing the "discrete" nature:
  // Frame 1: y = brick.y - 1. Collides? No (top is at y-ball.r = brick.y-1-7 = brick.y-8).
  // Wait, let's check collides again:
  // ball.y - ball.r < brick.y + brick.h && ball.y + ball.r > brick.y
  // brick.y-1-7 < brick.y+20 && brick.y-1+7 > brick.y => -8 < 20 && 6 > 0. YES.
  // So it should collide now.

  // To actually tunnel, the ball must be at a position where it DOESN'T collide,
  // and then move to a position where it ALSO DOESN'T collide, but passed THROUGH the brick.

  // Ball diameter = 14. Brick height = 20.
  // If ball.y + ball.r < brick.y, then it's above.
  // If ball.y - ball.r > brick.y + brick.h, then it's below.

  // For the ball to tunnel, it must be at y1 such that y1 + 7 < brick.y
  // And then at y2 such that y2 - 7 > brick.y + 20.
  // y2 - y1 > 20 + 14 = 34.
  // 1000 * 0.05 = 50.

  state.ball.y = brick.y - 10; // y + 7 = brick.y - 3 < brick.y (Above)
  state.ball.vy = 1000;

  // In a real game, we do: step(state, dt) then frame(ctx, state).
  // We need to implement a simple step here or import it.
  // Actually, let's just test if a hypothetical "corrected" version would have caught it.
  // But the prompt asks to prove the defect on current code.

  // On current code, we just call frame.
  // If we just call frame, and it's above, it doesn't collide.
  // If we just call frame, and it's below, it doesn't collide.
  // The "defect" is that there's no swept collision.

  frame(ctx, state); 
  // On current code, if it doesn't overlap at the exact moment of frame(), it's gone.
  // This test is more about the "missing feature" of swept collision.
});

import { test } from 'node:test';
import assert from 'node:assert';
import { createState, frame, WIDTH, HEIGHT, BALL_R } from '../game/neon.js';

const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1: Missing Bounce - Ball should bounce off a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below
  state.ball.vy = -100; // Moving up

  frame(ctx, state);
  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced and now be moving down');
});

test('D2: Sticky - Ball should be repositioned out of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball so it's deep inside the brick from the bottom
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h - 1; // Center is 1px above the bottom edge
  // Ball bottom is at y + 7 = brick.y + brick.h + 6.
  // Ball top is at y - 7 = brick.y + brick.h - 8.
  // Since brick.h = 20, brick.y + brick.h - 8 is definitely inside the brick.
  state.ball.vy = -100;

  frame(ctx, state);

  // After bounce from bottom, the ball should be at y - 7 = brick.y + brick.h
  // So y = brick.y + brick.h + 7
  assert.strictEqual(state.ball.y, brick.y + brick.h + BALL_R, 'Ball should be pushed out of the brick');
});

test('D3: Face vs Corner - Ball should bounce off the side', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; // Just to the left
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving right

  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced off the side');
});

test('D4: Double Inversion - Ball should not invert twice on a seam', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];

  // Ball is exactly on the seam between b1 and b2
  state.ball.x = b1.x + b1.w; 
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 100;

  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have inverted once, not twice');
});

test('D5: Tunneling - Ball should not jump over a brick', () => {
  const state = createState(5);
  const brick = state.bricks[0];

  // For a ball to tunnel, it must be above in one frame and below in the next
  // without ever being "inside" during the frame() check.
  // This requires simulating the step.

  // Current implementation is discrete. Let's prove it.
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; // Above
  state.ball.vy = 1000;

  // Simulate a step (manual because step is in neon.js)
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // 1000 * 0.05 = 50. y becomes brick.y + 40.

  // Now ball.y = brick.y + 40.
  // Ball top = 40 - 7 = 33.
  // Brick bottom = brick.y + 20.
  // 33 > 20. The ball is completely below the brick.

  frame(ctx, state);

  // If the ball tunneled, it's still moving down.
  assert.strictEqual(state.ball.vy, 1000, 'Ball tunneled through the brick');
});

# Playtest: Ball passes through bricks

Symptôme : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond
- **Famille** : Traversée (manque de réponse)
- **Symptôme joueur** : la balle traverse les briques sans changer de direction.
- **Cause** : `game/neon.js:175` — la collision est détectée et la brique est détruite, mais aucune modification de la vitesse de la balle n'est appliquée.
- **Invariant violé** : Toute collision avec un obstacle doit entraîner un changement de direction.
- **Déclencheur** : Tout chevauchement balle-brique.
- **Attendu** : La balle doit rebondir selon la face touchée.
- **Référence** : [AABB Collision Resolution](https://learnopengl.com/In-Practice/2D-Collision-Resolution) — inversion de la composante de vitesse perpendiculaire à la face touchée.
- **Cas test** :
  ```js
  test('D1: Missing Bounce - Ball should bounce off a brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h + 2; // Just below
    state.ball.vy = -100; // Moving up
    frame(ctx, state);
    assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced and now be moving down');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced and now be moving down` (`-100 !== 100`)
- **Discrimine** : une correction qui détruit la brique mais oublie d'inverser la vitesse.
- **Vert quand** : `state.ball.vy` est inversé lors d'un impact horizontal.
- **Révélé par** : Aucun (bloquant)

## D2 — Recouvrement collant
- **Famille** : Collant
- **Symptôme joueur** : la balle peut rester "coincée" dans une brique ou vibrer.
- **Cause** : Inversion de la vitesse sans repositionnement : la balle peut rester en collision au tour suivant.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de l'obstacle.
- **Déclencheur** : Pénétration profonde (ex: `ball.y = brick.y + brick.h - 1`).
- **Attendu** : La balle est repoussée à la surface de la brique.
- **Référence** : [AABB Resolution](https://learnopengl.com/In-Practice/2D-Collision-Resolution) — repositionnement basé sur la pénétration minimale.
- **Cas test** :
  ```js
  test('D2: Sticky - Ball should be repositioned out of brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h - 1;
    state.ball.vy = -100;
    frame(ctx, state);
    assert.strictEqual(state.ball.y, brick.y + brick.h + BALL_R, 'Ball should be pushed out of the brick');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be pushed out of the brick` (`67 !== 75`)
- **Discrimine** : une correction qui inverse la vitesse mais ne repositionne pas la balle.
- **Vert quand** : la position de la balle est corrigée pour ne plus chevaucher la brique.
- **Révélé par** : D1

## D3 — Confusion Face vs Coin
- **Famille** : Face vs coin
- **Symptôme joueur** : la balle rebondit verticalement alors qu'elle a touché le côté de la brique.
- **Cause** : Utilisation d'une inversion systématique de `vy` sans tester l'axe de collision.
- **Invariant violé** : L'axe inversé doit être celui de la plus petite pénétration.
- **Déclencheur** : Collision avec la face latérale d'une brique.
- **Attendu** : `vx` inversé lors d'un impact latéral.
- **Référence** : [AABB Collision](https://noonat.github.io/intersect/) — analyse des axes de collision.
- **Cas test** :
  ```js
  test('D3: Face vs Corner - Ball should bounce off the side', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - 2; 
    state.ball.y = brick.y + brick.h / 2;
    state.ball.vx = 100;
