content.text:
// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  frame,
  makeBricks,
  createState,
  BALL_R,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}


const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1: Missing Bounce - Ball should bounce off a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below
  state.ball.vy = -100; // Moving up
  frame(ctx, state);
  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced and now be moving down');
});

test('D2: Sticky - Ball should be repositioned out of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h - 1;
  state.ball.vy = -100;
  frame(ctx, state);
  assert.strictEqual(state.ball.y, brick.y + brick.h + BALL_R, 'Ball should be pushed out of the brick');
});

test('D3: Face vs Corner - Ball should bounce off the side', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; 
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving right
  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced off the side');
});

test('D4: Double Inversion - Ball should not invert twice on a seam', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  state.ball.x = b1.x + b1.w; 
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 100;
  frame(ctx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have inverted once, not twice');
});

test('D5: Tunneling - Ball should not jump over a brick', () => {
  const state = createState(5);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000;
  state.ball.y += state.ball.vy * 0.05; 
  frame(ctx, state);
  assert.notStrictEqual(state.ball.vy, 1000, 'Ball should have bounced instead of tunneling');
});

